function removeDuplicates(lst) {
    let uniqueList = [];
    for (let i = 0; i < lst.length; i++) {
        if (!uniqueList.includes(lst[i])) {
            uniqueList.push(lst[i]);
        }
    }
    return uniqueList;
}

